// Load the settlement rule set (embedded JSON). In production this is reloaded
// from a DB/remote config (hot-reload declared in node UI but not yet implemented).
const ruleSet = {
  version: '1.0',
  default_outcome: 'void',
  rules: [
    {
      id: 'rule_football_home_win',
      name: 'Football home win (ended)',
      priority: 10,
      condition: {
        operator: 'and',
        conditions: [
          { field: 'event.status', comparator: 'eq', value: 'ended' },
          { field: 'event.score.home', comparator: 'gt', value: '{{ $json.event.score.away }}' }
        ]
      },
      outcome: 'won'
    },
    {
      id: 'rule_football_home_loss',
      name: 'Football home loss (ended)',
      priority: 10,
      condition: {
        operator: 'and',
        conditions: [
          { field: 'event.status', comparator: 'eq', value: 'ended' },
          { field: 'event.score.home', comparator: 'lt', value: '{{ $json.event.score.away }}' }
        ]
      },
      outcome: 'lost'
    },
    {
      id: 'rule_tennis_retirement',
      name: 'Tennis retirement / abandoned',
      priority: 20,
      condition: {
        operator: 'or',
        conditions: [
          { field: 'event.status', comparator: 'eq', value: 'abandoned' },
          { field: 'event.status', comparator: 'eq', value: 'postponed' }
        ]
      },
      outcome: 'void'
    },
    {
      id: 'rule_default_void',
      name: 'Unmatched -> void (safe)',
      priority: 0,
      condition: { operator: 'or', conditions: [] },
      outcome: 'void'
    }
  ]
};

return [{
  json: {
    event: $json.event,
    odds: $json.odds,
    rule_set: ruleSet
  }
}];

// Evaluate settlement rule set via processing engine and emit SettlementResult
const { event, odds, rule_set } = $json;

// Build context for rule engine (mirrors processing_engine.settlement.rule_engine._build_context)
const context = {
  event: {
    id: event.id,
    sport: event.sport,
    league: event.league,
    status: event.status,
    home_team: event.home_team,
    away_team: event.away_team,
    score: event.score || { home: 0, away: 0 }
  },
  odds: odds || null
};

function getNested(obj, path) {
  return path.split('.').reduce((o, k) => (o && o[k] !== undefined ? o[k] : undefined), obj);
}

function evalCond(cond, ctx) {
  if (cond.operator) {
    const subs = cond.conditions || [];
    if (cond.operator === 'not') return !evalCond(subs[0], ctx);
    const results = subs.map(c => evalCond(c, ctx));
    return cond.operator === 'and' ? results.every(Boolean) : results.some(Boolean);
  }
  const actual = getNested(ctx, cond.field);
  const cmp = cond.comparator;
  const val = cond.value;
  switch (cmp) {
    case 'eq': return actual == val;
    case 'ne': return actual != val;
    case 'gt': return Number(actual) > Number(val);
    case 'gte': return Number(actual) >= Number(val);
    case 'lt': return Number(actual) < Number(val);
    case 'lte': return Number(actual) <= Number(val);
    case 'in': return Array.isArray(val) ? val.includes(actual) : actual == val;
    case 'contains': return String(actual).includes(String(val));
    default: return false;
  }
}

let outcome = rule_set.default_outcome;
let confidence = 0.5;
let matchedRule = null;
for (const rule of (rule_set.rules || []).sort((a, b) => b.priority - a.priority)) {
  try {
    if (evalCond(rule.condition, context)) {
      outcome = rule.outcome;
      confidence = 1.0;
      matchedRule = rule;
      break;
    }
  } catch (e) {
    // skip bad rule
  }
}

return [{
  json: {
    event_id: event.id,
    market_id: odds ? odds.market_id : 'unknown',
    selection_id: odds ? odds.selection_id : 'unknown',
    outcome,
    settled_at: new Date().toISOString(),
    source: 'auto',
    confidence,
    matched_rule: matchedRule ? matchedRule.id : null,
    rule_set_version: rule_set.version
  }
}];

// Forward settlement result to downstream systems (CRM, risk, reporting)
const result = $json;
return [{
  json: {
    target: 'sportsbook-crm',
    action: 'settle_bet',
    payload: {
      event_id: result.event_id,
      market_id: result.market_id,
      selection_id: result.selection_id,
      outcome: result.outcome,
      settled_at: result.settled_at,
      confidence: result.confidence
    }
  }
}];

// Audit log entry for every automated settlement decision (regulatory requirement)
const result = $json;
return [{
  json: {
    target: 'audit-log',
    action: 'record_settlement',
    payload: {
      event_id: result.event_id,
      market_id: result.market_id,
      selection_id: result.selection_id,
      outcome: result.outcome,
      source: result.source,
      confidence: result.confidence,
      matched_rule: result.matched_rule,
      settled_at: result.settled_at
    }
  }
}];
